#include "fuse/store.h"
namespace fuse {
Status fsj_build(const JournalRecordInput*in,Buffer*out,Digest256*rh){if(!in||!out||(!in->payload.data&&in->payload.size))return Status::InvalidArgument;auto st=fcb_validate(in->payload);if(st!=Status::Ok)return st;out->assign((size_t)(FSJ1_HEADER_SIZE+in->payload.size+32),0);auto*p=out->data();p[0]='F';p[1]='S';p[2]='J';p[3]='1';put_u16_le(p+4,1);put_u16_le(p+6,(u16)FSJ1_HEADER_SIZE);put_u32_le(p+8,in->flags);put_u64_le(p+12,in->sequence);bytes_copy(p+20,in->mission_id.bytes.data(),16);put_u64_le(p+36,in->mission_version);put_u32_le(p+44,in->event_type);put_u32_le(p+48,0);put_u64_le(p+52,in->wall_time_100ns);put_u64_le(p+60,in->monotonic_ticks);bytes_copy(p+68,in->previous_record_hash.bytes.data(),32);put_u64_le(p+100,in->payload.size);Digest256 ph{};st=sha256(in->payload,&ph);if(st!=Status::Ok)return st;bytes_copy(p+108,ph.bytes.data(),32);bytes_copy(p+140,in->payload.data,in->payload.size);Digest256 h{};st=sha256({p,140+in->payload.size},&h);if(st!=Status::Ok)return st;bytes_copy(p+140+in->payload.size,h.bytes.data(),32);if(rh)*rh=h;return Status::Ok;}
Status fsj_validate(ByteSpan r){if(!r.data||r.size<172)return Status::BadLength;auto*p=r.data;if(p[0]!='F'||p[1]!='S'||p[2]!='J'||p[3]!='1')return Status::BadMagic;if(get_u16_le(p+4)!=1||get_u16_le(p+6)!=140)return Status::BadVersion;u64 n=get_u64_le(p+100);if(n>GENESIS_MAX_RECORD||140+n+32!=r.size)return Status::BadLength;Digest256 ph{};auto st=sha256({p+140,n},&ph);if(st!=Status::Ok)return st;if(!bytes_equal(ph.bytes.data(),p+108,32))return Status::BadDigest;if((st=fcb_validate({p+140,n}))!=Status::Ok)return st;Digest256 h{};st=sha256({p,140+n},&h);if(st!=Status::Ok)return st;return bytes_equal(h.bytes.data(),p+140+n,32)?Status::Ok:Status::BadDigest;}
Status fsj_view(ByteSpan r,JournalRecordView*out){if(!out)return Status::InvalidArgument;auto st=fsj_validate(r);if(st!=Status::Ok)return st;auto*p=r.data;u64 n=get_u64_le(p+100);out->sequence=get_u64_le(p+12);bytes_copy(out->mission_id.bytes.data(),p+20,16);out->mission_version=get_u64_le(p+36);out->event_type=get_u32_le(p+44);bytes_copy(out->previous_record_hash.bytes.data(),p+68,32);out->payload={p+140,n};bytes_copy(out->record_hash.bytes.data(),p+140+n,32);return Status::Ok;}
}
